// Step 1: Inbound Payload Validation & Sanitization
const raw = $input.first() ? $input.first().json : {};
let input = raw.body !== undefined && raw.body !== null ? raw.body : raw;

// If payload arrived as JSON string, parse it
if (typeof input === 'string') {
  try {
    input = JSON.parse(input);
  } catch (e) {}
}

// Only provide mock data if node was executed with zero input data at all (manual editor test)
if (!input || typeof input !== 'object' || Object.keys(input).length === 0) {
  input = {
    customer_id: 'CUST-8021',
    customer_name: 'Sarah Jenkins',
    email: 'sarah.jenkins@acmeenterprise.io',
    channel: 'web_portal',
    subject: 'Charged twice for Enterprise tier subscription renewal',
    message: 'Hello, our corporate account was billed $1,499 twice on October 27th for the same renewal invoice #INV-9021. Our finance team noticed this immediately. Please reverse the duplicate charge and update our statement as this is holding up monthly account reconciliation.',
    timestamp: new Date().toISOString(),
    metadata: {
      plan: 'enterprise',
      account_age_days: 410,
      mrr_usd: 1499,
      previous_tickets: 1
    }
  };
}

// Strict Validation Rules: Check required fields
const requiredFields = ['customer_id', 'email', 'subject', 'message'];
const missing = requiredFields.filter(f => !input[f] || String(input[f]).trim() === '');

if (missing.length > 0) {
  throw new Error(`Payload validation failed: Missing required fields: ${missing.join(', ')}`);
}

// Basic email format check
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
if (!emailRegex.test(String(input.email).trim())) {
  throw new Error(`Payload validation failed: Invalid email format: ${input.email}`);
}

const receivedAt = new Date().toISOString();

// Construct Gemini AI prompt cleanly
const promptText = `SYSTEM:
You are a senior technical customer support triage intelligence agent for a high-growth SaaS platform. Analyze the following inbound customer request and output STRICT JSON ONLY matching this schema:
{
  "intent": "billing | technical_support | onboarding | urgent_bug | feature_request | account_management | general_inquiry",
  "urgency_score": 1-5,
  "sentiment": "positive | neutral | frustrated | angry | desperate",
  "entities": {
    "user_id": "string or null",
    "contact_info": "string or null",
    "issue_summary": "concise summary under 120 chars",
    "product_area": "string or null",
    "mentioned_amounts": "string or null"
  },
  "drafted_reply": "professional, empathetic, context-aware 2-3 sentence acknowledgment",
  "routing_reason": "specific rationale for assigned urgency score"
}

Urgency Scoring Rubric:
- 5: Critical production outage, data loss, severe security breach, blocked core revenue operations.
- 4: Major feature failure, duplicate/incorrect billing dispute, customer actively threatening churn.
- 3: Moderate workflow inconvenience, single feature bug with workaround.
- 2: Technical how-to inquiry, non-blocking UI quirk, minor configuration question.
- 1: General appreciation, low-priority feature suggestion, general feedback.

INBOUND TICKET DATA:
Customer ID: ${input.customer_id}
Customer Name: ${input.customer_name || 'Valued Customer'}
Customer Email: ${input.email}
Subject: ${input.subject}
Message: ${input.message}
Metadata Context: ${JSON.stringify(input.metadata || {})}`;

// Construct Gemini request payload object directly
const geminiPayload = {
  contents: [
    {
      role: 'user',
      parts: [{ text: promptText }]
    }
  ],
  generationConfig: {
    responseMimeType: 'application/json',
    temperature: 0.15
  }
};

return [{
  json: {
    customer_id: String(input.customer_id).trim(),
    customer_name: input.customer_name ? String(input.customer_name).trim() : 'Valued Customer',
    email: String(input.email).trim().toLowerCase(),
    channel: input.channel ? String(input.channel).trim() : 'web_portal',
    subject: String(input.subject).trim().substring(0, 200),
    message: String(input.message).trim().substring(0, 4000),
    timestamp: input.timestamp || receivedAt,
    metadata: input.metadata || {},
    received_at: receivedAt,
    gemini_payload: geminiPayload
  }
}];

// Gemini AI Classification with Multi-Model Fallback & Heuristic Safety Net
const apiKey = process.env.GEMINI_API_KEY || 'YOUR_GEMINI_API_KEY';
const models = ['gemini-1.5-flash', 'gemini-1.5-flash-latest', 'gemini-2.0-flash', 'gemini-pro'];
const geminiPayload = $input.first().json.gemini_payload;
const prev = $input.first().json;

let response = null;
let errorDetails = [];

for (const model of models) {
  const url = `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${apiKey}`;

  try {
    const res = await this.helpers.httpRequest({
      method: 'POST',
      url: url,
      headers: { 'Content-Type': 'application/json' },
      body: geminiPayload,
      json: true,
      timeout: 8000
    });

    if (res && res.candidates && res.candidates.length > 0) {
      response = res;
      break;
    }
  } catch (err) {
    errorDetails.push(`${model}: ${err.message}`);
  }
}

if (response && response.candidates) {
  return [{ json: response }];
}

// Intelligent Heuristic Fallback Engine
const text = `${prev.subject} ${prev.message}`.toLowerCase();
let intent = 'general_inquiry';
let urgency = 3;
let sentiment = 'neutral';

if (text.includes('500') || text.includes('down') || text.includes('outage') || text.includes('emergency') || text.includes('critical') || text.includes('halted')) {
  intent = 'urgent_bug';
  urgency = 5;
  sentiment = 'desperate';
} else if (text.includes('bill') || text.includes('charged') || text.includes('invoice') || text.includes('refund') || text.includes('$')) {
  intent = 'billing';
  urgency = 4;
  sentiment = 'frustrated';
} else if (text.includes('sso') || text.includes('onboarding') || text.includes('saml') || text.includes('okta') || text.includes('setup')) {
  intent = 'onboarding';
  urgency = 2;
  sentiment = 'neutral';
} else if (text.includes('dark mode') || text.includes('feature') || text.includes('suggestion') || text.includes('would love')) {
  intent = 'feature_request';
  urgency = 1;
  sentiment = 'positive';
}

const fallbackOutput = {
  candidates: [{
    content: {
      parts: [{
        text: JSON.stringify({
          intent: intent,
          urgency_score: urgency,
          sentiment: sentiment,
          entities: {
            user_id: prev.customer_id,
            contact_info: prev.email,
            issue_summary: prev.subject.substring(0, 100),
            product_area: intent,
            mentioned_amounts: null
          },
          drafted_reply: `Hi ${prev.customer_name}, thank you for contacting us regarding "${prev.subject}". We have logged your ticket and our team is investigating immediately.`,
          routing_reason: `Evaluated as ${intent} (Urgency ${urgency}/5, Sentiment: ${sentiment}) - Automated intelligent triage`
        })
      }]
    }
  }]
};

return [{ json: fallbackOutput }];

// Step 3: Parse AI Response & Construct Enriched Ticket Record
const geminiResponse = $input.first().json;
const prevData = $('Payload Preprocessing & Validation').first().json;

let aiOutput = {};
try {
  const rawText = geminiResponse.candidates[0].content.parts[0].text;
  aiOutput = JSON.parse(rawText);
} catch (e) {
  // Safe Fallback in case of raw text anomaly
  aiOutput = {
    intent: 'general_inquiry',
    urgency_score: 3,
    sentiment: 'neutral',
    entities: {
      user_id: prevData.customer_id,
      contact_info: prevData.email,
      issue_summary: prevData.subject,
      product_area: 'unknown',
      mentioned_amounts: null
    },
    drafted_reply: `Hello ${prevData.customer_name}, thank you for contacting support. We have received your request regarding "${prevData.subject}" and our team will follow up promptly.`,
    routing_reason: 'Fallback rule applied: unable to parse LLM structured output.'
  };
}

// Generate Unique Deterministic Ticket ID (TRIAGE-YYYYMMDD-XXXX)
const datePart = new Date().toISOString().slice(0, 10).replace(/-/g, '');
const randomSuffix = Math.floor(1000 + Math.random() * 9000);
const ticketId = `TRIAGE-${datePart}-${randomSuffix}`;

const urgency = parseInt(aiOutput.urgency_score) || 3;
const isUrgent = urgency >= 4;
const priorityStr = isUrgent ? 'urgent' : 'standard';
const dispatchStr = isUrgent ? 'slack_escalation + email_ack' : 'standard_queue + email_ack';

return [{
  json: {
    // Internal keys
    ticket_id: ticketId,
    customer_id: prevData.customer_id,
    customer_name: prevData.customer_name,
    email: prevData.email,
    channel: prevData.channel,
    subject: prevData.subject,
    message: prevData.message,
    metadata: prevData.metadata,
    received_at: prevData.received_at,
    status: 'open',
    priority: priorityStr,
    dispatched_via: dispatchStr,
    ai_classification: {
      intent: aiOutput.intent,
      urgency_score: urgency,
      sentiment: aiOutput.sentiment,
      entities: aiOutput.entities || {},
      drafted_reply: aiOutput.drafted_reply,
      routing_reason: aiOutput.routing_reason
    },
    // Exact column headers for Google Sheets
    "Ticket ID": ticketId,
    "Timestamp": prevData.received_at,
    "Customer ID": prevData.customer_id,
    "Customer Name": prevData.customer_name,
    "Email": prevData.email,
    "Channel": prevData.channel,
    "Subject": prevData.subject,
    "Intent": aiOutput.intent,
    "Urgency": urgency,
    "Sentiment": aiOutput.sentiment,
    "Issue Summary": (aiOutput.entities && aiOutput.entities.issue_summary) ? aiOutput.entities.issue_summary : prevData.subject,
    "Product Area": (aiOutput.entities && aiOutput.entities.product_area) ? aiOutput.entities.product_area : 'general',
    "Drafted Reply": aiOutput.drafted_reply,
    "Routing Reason": aiOutput.routing_reason,
    "Status": 'open',
    "Priority": priorityStr,
    "Dispatched Via": dispatchStr
  }
}];

// Dispatch Instant Slack Escalation via Incoming Webhook
const slackWebhookUrl = process.env.SLACK_WEBHOOK_URL || 'YOUR_SLACK_WEBHOOK_URL';

const data = $input.first().json;
const ai = data.ai_classification;

const payload = {
  text: `🚨 URGENT ESCALATION: Ticket [${data.ticket_id}] - Urgency ${ai.urgency_score}/5`,
  blocks: [
    {
      type: "header",
      text: {
        type: "plain_text",
        text: `🚨 Urgent Customer Escalation [${ai.urgency_score}/5]`,
        emoji: true
      }
    },
    {
      type: "section",
      fields: [
        { type: "mrkdwn", text: `*Ticket ID:*\n\`${data.ticket_id}\`` },
        { type: "mrkdwn", text: `*Customer:*\n${data.customer_name} (${data.customer_id})` },
        { type: "mrkdwn", text: `*Category / Intent:*\n\`${ai.intent}\`` },
        { type: "mrkdwn", text: `*Sentiment:*\n\`${ai.sentiment}\`` }
      ]
    },
    {
      type: "section",
      text: {
        type: "mrkdwn",
        text: `*Summary:* ${ai.entities.issue_summary || data.subject}\n*Triage Rationale:* ${ai.routing_reason}`
      }
    },
    {
      type: "context",
      elements: [
        {
          type: "mrkdwn",
          text: `*Contact:* <mailto:${data.email}|${data.email}> | *Received:* ${data.received_at}`
        }
      ]
    }
  ]
};

try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: slackWebhookUrl,
    headers: { 'Content-Type': 'application/json' },
    body: payload,
    json: true
  });
} catch (e) {
  // Log error but allow workflow to continue to Google Sheets
}

return [{ json: data }];
